import sbt.*

/** Splits sources generated by ScalablyTyped into one sbt module per top-level package.
  *
  * Generated sources live in `<generatedRoot>/io.kinoplan.sjr/<package>/...`. Every package becomes
  * `sjr-modules/<package>`, files directly in the namespace go to the `base` module that all others
  * depend on. The module graph is written to an sbt file so it is picked up on the next `reload`.
  */
object FacadeSplitter {

  val BaseModule = "base"

  private val Namespace = "io.kinoplan.sjr"
  private val PackageRef = (Namespace.replace(".", "\\.") + """\.([A-Za-z0-9_]+)""").r

  def split(generatedRoot: File, modulesDir: File, sbtFile: File, scalaDir: String): Unit = {
    val namespaceRoot = generatedRoot / Namespace
    val children = IO.listFiles(namespaceRoot).toList
    val packages = children.filter(_.isDirectory).map(_.getName).sorted
    val known = packages.toSet

    val dependencies = packages
      .map(p => p -> referencedPackages(namespaceRoot / p, known - p))
      .toMap

    ensureAcyclic(dependencies)

    def sourcesDir(module: String) = modulesDir / module / "src" / "main" / scalaDir /
      Namespace.replace('.', '/')

    (BaseModule :: packages)
      .foreach(module => IO.delete(modulesDir / module / "src" / "main" / scalaDir))

    children.filter(_.isFile).foreach(f => IO.copyFile(f, sourcesDir(BaseModule) / f.getName))

    packages.foreach(p => IO.copyDirectory(namespaceRoot / p, sourcesDir(p) / p))

    val projects =
      (BaseModule -> Nil) :: packages.map(p => p -> (BaseModule :: dependencies(p).toList.sorted))

    IO.write(sbtFile, render(projects))
  }

  def projectId(module: String): String = "mod" + module.capitalize

  private def referencedPackages(dir: File, candidates: Set[String]): Set[String] =
    (dir ** "*.scala")
      .get
      .iterator
      .flatMap(f => PackageRef.findAllMatchIn(IO.read(f)).map(_.group(1)))
      .toSet
      .intersect(candidates)

  private def ensureAcyclic(graph: Map[String, Set[String]]): Unit = {
    def visit(node: String, path: List[String], done: scala.collection.mutable.Set[String]): Unit =
      if (path.contains(node)) sys.error(
        s"Facade packages form a cycle, merge them into one module: ${(node :: path).reverse.mkString(" -> ")}"
      )
      else if (done.add(node)) graph(node).foreach(visit(_, node :: path, done))

    val done = scala.collection.mutable.Set.empty[String]

    graph.keys.foreach(visit(_, Nil, done))
  }

  private def render(projects: List[(String, List[String])]): String = {
    val definitions = projects.map { case (module, deps) =>
      val dependsOn =
        if (deps.isEmpty) ""
        else deps.map(projectId).mkString(".dependsOn(", ", ", ")")
      s"""lazy val ${projectId(module)} = ProjectSettings.facadeModule("$module")$dependsOn"""
    }

    val aggregate = projects
      .map { case (module, _) =>
        projectId(module)
      }
      .mkString(", ")

    s"""// Generated by FacadeSplitter (sbt genFacades), do not edit
       |// format: off
       |
       |${definitions.mkString("\n")}
       |
       |lazy val facadeModules = project
       |  .in(file("sjr-modules"))
       |  .aggregate($aggregate)
       |  .settings(publish / skip := true)
       |""".stripMargin
  }

}
